import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Chip,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import { applicationsAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const Institutions = () => {
  const { currentUser } = useAuth();
  const [institutions, setInstitutions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [selectedInstitution, setSelectedInstitution] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  // Mock data - in real app, you'd fetch from API
  useEffect(() => {
    const mockInstitutions = [
      {
        id: 'inst1',
        name: 'National University of Lesotho',
        description: 'The premier institution of higher learning in Lesotho offering diverse programs.',
        location: 'Roma, Lesotho',
        faculties: [
          {
            id: 'f1',
            name: 'Faculty of Science & Technology',
            courses: [
              { id: 'c1', name: 'Computer Science', duration: '4 years', fees: 15000, seats: 50 },
              { id: 'c2', name: 'Electrical Engineering', duration: '4 years', fees: 18000, seats: 40 }
            ]
          },
          {
            id: 'f2',
            name: 'Faculty of Humanities',
            courses: [
              { id: 'c3', name: 'Business Administration', duration: '3 years', fees: 12000, seats: 60 },
              { id: 'c4', name: 'Education', duration: '4 years', fees: 10000, seats: 80 }
            ]
          }
        ]
      },
      {
        id: 'inst2',
        name: 'Limkokwing University',
        description: 'Creative innovation university focusing on technology and design.',
        location: 'Maseru, Lesotho',
        faculties: [
          {
            id: 'f3',
            name: 'Faculty of Creative Technology',
            courses: [
              { id: 'c5', name: 'Graphic Design', duration: '3 years', fees: 16000, seats: 30 },
              { id: 'c6', name: 'Software Engineering', duration: '4 years', fees: 17000, seats: 35 }
            ]
          }
        ]
      }
    ];
    setInstitutions(mockInstitutions);
  }, []);

  const applyForCourse = async (institutionId, courseId) => {
    try {
      setLoading(true);
      setError('');
      setSuccess('');
      
      await applicationsAPI.applyForCourse({
        institutionId,
        courseId,
        documents: []
      });
      
      setSuccess('Successfully applied for the course!');
      setDialogOpen(false);
    } catch (err) {
      console.error('Apply error:', err);
      setError(err.response?.data?.error || 'Failed to apply for course. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const openInstitutionDetails = (institution) => {
    setSelectedInstitution(institution);
    setDialogOpen(true);
  };

  const closeDialog = () => {
    setDialogOpen(false);
    setSelectedInstitution(null);
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Higher Learning Institutions
      </Typography>
      <Typography variant="body1" color="textSecondary" sx={{ mb: 3 }}>
        Discover and apply to courses at institutions across Lesotho
      </Typography>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mb: 2 }}>
          {success}
        </Alert>
      )}

      <Grid container spacing={3}>
        {institutions.map((institution) => (
          <Grid item xs={12} key={institution.id}>
            <Card>
              <CardContent>
                <Typography variant="h5" gutterBottom>
                  {institution.name}
                </Typography>
                <Typography variant="body2" color="textSecondary" gutterBottom>
                  {institution.location}
                </Typography>
                <Typography variant="body1" paragraph>
                  {institution.description}
                </Typography>
                
                <Typography variant="h6" gutterBottom>
                  Faculties & Courses
                </Typography>
                
                {institution.faculties.map((faculty) => (
                  <Box key={faculty.id} sx={{ mb: 2, pl: 2 }}>
                    <Typography variant="subtitle1" color="primary" gutterBottom>
                      {faculty.name}
                    </Typography>
                    <Grid container spacing={1}>
                      {faculty.courses.map((course) => (
                        <Grid item xs={12} md={6} key={course.id}>
                          <Paper variant="outlined" sx={{ p: 1.5 }}>
                            <Typography variant="body2" fontWeight="bold">
                              {course.name}
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                              Duration: {course.duration} • Fees: M{course.fees}
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                              Seats: {course.seats} available
                            </Typography>
                            <Button
                              variant="outlined"
                              size="small"
                              onClick={() => applyForCourse(institution.id, course.id)}
                              disabled={loading}
                              sx={{ mt: 1 }}
                            >
                              {loading ? 'Applying...' : 'Apply Now'}
                            </Button>
                          </Paper>
                        </Grid>
                      ))}
                    </Grid>
                  </Box>
                ))}

                <Button
                  variant="contained"
                  onClick={() => openInstitutionDetails(institution)}
                  sx={{ mt: 2 }}
                >
                  View All Courses
                </Button>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Institution Details Dialog */}
      <Dialog open={dialogOpen} onClose={closeDialog} maxWidth="md" fullWidth>
        <DialogTitle>
          {selectedInstitution?.name} - All Courses
        </DialogTitle>
        <DialogContent>
          {selectedInstitution && (
            <Box>
              <Typography variant="body1" paragraph>
                {selectedInstitution.description}
              </Typography>
              
              {selectedInstitution.faculties.map((faculty) => (
                <Box key={faculty.id} sx={{ mb: 3 }}>
                  <Typography variant="h6" gutterBottom color="primary">
                    {faculty.name}
                  </Typography>
                  <Grid container spacing={2}>
                    {faculty.courses.map((course) => (
                      <Grid item xs={12} key={course.id}>
                        <Paper variant="outlined" sx={{ p: 2 }}>
                          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
                            <Box>
                              <Typography variant="subtitle1" fontWeight="bold">
                                {course.name}
                              </Typography>
                              <Typography variant="body2" color="textSecondary">
                                Duration: {course.duration} • Fees: M{course.fees}
                              </Typography>
                              <Typography variant="body2" color="textSecondary">
                                Seats Available: {course.seats}
                              </Typography>
                            </Box>
                            <Button
                              variant="contained"
                              size="small"
                              onClick={() => applyForCourse(selectedInstitution.id, course.id)}
                              disabled={loading}
                            >
                              {loading ? 'Applying...' : 'Apply'}
                            </Button>
                          </Box>
                        </Paper>
                      </Grid>
                    ))}
                  </Grid>
                </Box>
              ))}
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closeDialog}>Close</Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

export default Institutions;
